// Phosphor fallbacks for brand icons with no SVG data available
const BRAND_FALLBACK_ICON_MAP: Record<string, Icon> = {
  amazonsns: ChatCircle,
  cohere: Robot,
  deepl: Globe,
  elasticsearch: Database,
  pinecone: Database,
  pushover: ChatCircle,
};

function BrandNodeIcon({
  slug,
  size,
  className,
}: {
  slug: string;
  size: number;
  className?: string;
}) {
  const normalizedSlug = slug.toLowerCase();
  const local = LOCAL_BRAND_ICONS[normalizedSlug];

  if (local) {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        aria-hidden
        className={`node-brand-icon${className ? ` ${className}` : ""}`}
      >
        <path d={local.path} fill={local.hex} />
      </svg>
    );
  }

  const FallbackIcon =
    BRAND_FALLBACK_ICON_MAP[normalizedSlug] ?? CircleDashed;
  return (
    <FallbackIcon
      size={size}
      weight="regular"
      aria-hidden
      className={className}
    />
  );
}

export function isBrandIconName(
  name: string | null | undefined,
): name is `brand:${string}` {
  return typeof name === "string" && name.startsWith("brand:");
}

export function NodeIcon({
  name,
  size = 20,
  className,
}: {
  name: string | null | undefined;
  size?: number;
  className?: string;
}) {
  if (isBrandIconName(name)) {
    const slug = name.slice("brand:".length);
    return <BrandNodeIcon slug={slug} size={size} className={className} />;
  }

  const IconComponent = name ? ICON_MAP[name] : undefined;
  if (IconComponent) {
    return (
      <IconComponent
        size={size}
        weight="regular"
        aria-hidden
        className={className}
      />
    );
  }

  const LucideComponent = name ? LUCIDE_ICON_MAP[name] : undefined;
  if (LucideComponent) {
    return (
      <LucideComponent
        size={size}
        strokeWidth={2}
        aria-hidden
        className={className}
      />
    );
  }

  return (
    <CircleDashed
      size={size}
      weight="regular"
      aria-hidden
      className={className}
    />
  );
}
